```c
inline Buffer<enc>
buffer_memchr(npy_ucs4 ch, int len)
{
    Buffer<enc> newbuf = *this;
    switch (enc) {
    case ENCODING::ASCII:
        newbuf.buf = (char *) memchr(buf, ch, len);
        break;
    case ENCODING::UTF32:
        newbuf.buf = (char *) wmemchr((wchar_t *) buf, ch, len);
        break;
    }
    return newbuf;
}
