ub.com/users/mhvk/orgs","repos_url":"https://api.github.com/users/mhvk/repos","events_url":"https://api.github.com/users/mhvk/events{/privacy}","received_events_url":"https://api.github.com/users/mhvk/received_events","type":"User","site_admin":false},"body":"#25171 added string ufuncs, but unfortunately did not properly update the rather sparse test suite for `chararray`, in particular failing to test the various fast paths that were created. While one bug was fixed in #25484, not all were: as noted in #25513, the present version causes segfaults in `astropy`. It turned out there were multiple mistakes:
1. The `memchr` version of `findchar` always returns 0 for the offset;
2. The fast-track code for "no replacement possible" gives empty strings instead of a copy of the input;
3. In replacements, the length of the remaining buffer is not tracked, leading to buffer overflow.

These 3 commits fix those bugs, adding tests to avoid regressions.

