+    if (len2 == 0) {
+        return (npy_intp) start;
+    }
+    if (len2 == 1) {
+        npy_intp result;
+        switch (enc) {
+            case ENCODING::UTF8:
+            {
+                if (num_bytes_for_utf8_character((const unsigned char *)buf1.buf) > 1) {
+                    goto multibyte_search;
+                }
